/* ================= village sites, flattened into the terrain ================= */
const built = new Set();
const SITES = [
  {x:37,z:12,w:5,d:4,t:'cottage'}, {x:46,z:15,w:4,d:4,t:'tall'},
  {x:54,z:21,w:3,d:3,t:'tower'},   {x:43,z:23,w:7,d:5,t:'barn'},
  {x:37,z:29,w:4,d:5,t:'tall'},    {x:53,z:29,w:5,d:4,t:'cottage'},
  {x:39,z:37,w:5,d:4,t:'cottage'}, {x:48,z:39,w:4,d:4,t:'tall'},
  {x:55,z:42,w:3,d:3,t:'tower',pyr:true}, {x:37,z:45,w:6,d:4,t:'barn'},
  {x:46,z:47,w:5,d:4,t:'cottage'}, {x:54,z:49,w:4,d:4,t:'tall'},
  {x:44,z:53,w:4,d:4,t:'cottage'},
  {x:9, z:23,w:4,d:4,t:'cottage',west:true}, {x:6, z:30,w:4,d:4,t:'tall',west:true},
];
function flatten(x0, z0, w, d){
  let mx = 4;
  for(let z = z0 - 1; z <= z0 + d; z++) for(let x = x0 - 1; x <= x0 + w; x++)
    if(x >= 0 && z >= 0 && x < W && z < W) mx = Math.max(mx, H[key2(x, z)]);
