  s.chim = (s.t === 'cottage' || s.t === 'barn');
});
const WELL = {x:44, z:32, w:3, d:3};
WELL.F = flatten(44, 32, 3, 3);

/* ================= bridge landing across the river at z = 33 ================= */
const BZ = 33;
let bwx0 = -1, bwx1 = -1;
