    const x = 2 + Math.floor(rng() * (W - 4)), z = 2 + Math.floor(rng() * (W - 4));
    const k = key2(x, z);
    if(built.has(k) || pathSet.has(k)) continue;
    const h = H[k];
    if(h < 5 || h >= 14) continue;
    if(H[key2(x-1,z)] < 4 || H[key2(x+1,z)] < 4 || H[key2(x,z-1)] < 4 || H[key2(x,z+1)] < 4) continue;
    let nearPath = false;
    for(let dz = -1; dz <= 1; dz++) for(let dx = -1; dx <= 1; dx++) if(pathSet.has(key2(x+dx, z+dz))) nearPath = true;
    if(nearPath) continue;
    let inPad = false;
    for(const s of SITES) if(x >= s.x - 2 && x <= s.x + s.w + 1 && z >= s.z - 2 && z <= s.z + s.d + 1){ inPad = true; break; }
    if(inPad) continue;
    let crowded = false;
    for(const t of trees) if(Math.max(Math.abs(t.x - x), Math.abs(t.z - z)) < 4){ crowded = true; break; }
    if(crowded) continue;
    trees.push({x, z, pine: rng() < 0.4});
  }
}

/* ================= voxel buffers (one merged instanced mesh for all solids) ================= */
const solid = [], water = [], wins = [];
const occ = new Set();
const vk = (x, y, z) => x | (z << 6) | (y << 12);
function S(x, y, z, hex){
  const k = vk(x, y, z);
  if(occ.has(k)) return;
  occ.add(k);
  solid.push(x, y, z, hex);
}

/* ================= terrain: exposed shell + strata, water fill ================= */
const hAt = (x, z) => (x < 0 || z < 0 || x >= W || z >= W) ? 0 : H[key2(x, z)];
function topColorFor(x, z, h){
  const k = key2(x, z);
  if(pathSet.has(k)) return vary(rng() < 0.28 ? C.cobbleD : C.cobble, 0.06);
  if(built.has(k)) return vary(C.dirtD, 0.06);
  if(h <= WATER_TOP) return vary(C.sand, 0.05);
  const d = Math.abs(x + 0.5 - riverX(z));
  if(h <= 5 && d < 9) return vary(C.sand, 0.05);
  if(h >= 14) return vary(C.rock, 0.05);
  return vary(rng() < 0.16 ? C.grassL : C.grass, 0.07);
}
for(let z = 0; z < W; z++) for(let x = 0; x < W; x++){
  const h = H[key2(x, z)];
  const m = Math.min(hAt(x-1, z), hAt(x+1, z), hAt(x, z-1), hAt(x, z+1));
  const y0 = h <= WATER_TOP ? 0 : m;   // river beds stay solid under the transparent water
  const top = topColorFor(x, z, h);
  for(let y = y0; y < h; y++){
    let hex;
    if(y === h - 1) hex = top;
    else if(y >= h - 3) hex = vary(C.dirt, 0.07);
    else hex = vary(C.stoneD, 0.06);
    S(x, y, z, hex);
  }
  if(h <= WATER_TOP) for(let y = h; y <= WATER_TOP; y++) water.push(x, y, z, vary(C.water, 0.06));
}

/* ================= roof builders ================= */
function gableRoof(x0, z0, w, d, y0, hex, gableHex){
  const alongX = w >= d;
  let ridge = y0;
  const tile = cap => vary(cap ? mul(hex, 0.84) : hex, 0.055);
  if(alongX){
    let s = 0;
    while(true){
      const za = z0 - 1 + s, zb = z0 + d - s;
      if(za > zb) break;
      const y = y0 + s; ridge = y;
      const cap = (zb - za) <= 1;
      for(let x = x0; x < x0 + w; x++){
        S(x, y, za, tile(cap));
        if(zb !== za) S(x, y, zb, tile(cap));
      }
      s++;
    }
    if(gableHex) for(let ss = 0; ss < s; ss++){
      const y = y0 + ss, za = z0 - 1 + ss, zb = z0 + d - ss;
      for(let z = za + 1; z < zb; z++){
        S(x0, y, z, vary(gableHex, 0.05));
        S(x0 + w - 1, y, z, vary(gableHex, 0.05));
      }
    }
  } else {
    let s = 0;
    while(true){
      const xa = x0 - 1 + s, xb = x0 + w - s;
      if(xa > xb) break;
      const y = y0 + s; ridge = y;
      const cap = (xb - xa) <= 1;
      for(let z = z0; z < z0 + d; z++){
        S(xa, y, z, tile(cap));
        if(xb !== xa) S(xb, y, z, tile(cap));
      }
      s++;
    }
    if(gableHex) for(let ss = 0; ss < s; ss++){
      const y = y0 + ss, xa = x0 - 1 + ss, xb = x0 + w - ss;
      for(let x = xa + 1; x < xb; x++){
        S(x, y, z0, vary(gableHex, 0.05));
        S(x, y, z0 + d - 1, vary(gableHex, 0.05));
      }
    }
  }
  return ridge;
}
function pyramidRoof(x0, z0, w, d, y0, hex){
  let s = 0;
  while(true){
    const xa = x0 + s, xb = x0 + w - 1 - s, za = z0 + s, zb = z0 + d - 1 - s;
    if(xa > xb || za > zb) break;
    const y = y0 + s;
    if(xa === xb && za === zb){ S(xa, y, za, vary(hex, 0.05)); break; }
    for(let x = xa; x <= xb; x++){ S(x, y, za, vary(hex, 0.05)); S(x, y, zb, vary(hex, 0.05)); }
    for(let z = za + 1; z < zb; z++){ S(xa, y, z, vary(hex, 0.05)); S(xb, y, z, vary(hex, 0.05)); }
    s++;
  }
}
function perimOrdered(x0, z0, w, d){
  const a = [];
  for(let x = x0; x < x0 + w; x++) a.push([x, z0]);
  for(let z = z0 + 1; z < z0 + d; z++) a.push([x0 + w - 1, z]);
  for(let x = x0 + w - 2; x >= x0; x--) a.push([x, z0 + d - 1]);
  for(let z = z0 + d - 2; z > z0; z--) a.push([x0, z]);
  return a;
